INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','articles-place-names','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"articles-place-names","title":"Articles with place names and institutions","level":"A2","order":20,"summary":"Learn common geographical patterns and distinguish an institution’s purpose from its physical building.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Names that usually take no article","Names that commonly take the","Institutional purpose and the building","Names inside larger noun phrases"],"rules":[{"title":"Names that usually take no article","explanation":"Most ordinary country and city names take no article, as do continents, individual mountains named with Mount, and lakes named with Lake. These are naming conventions rather than a universal rule for all proper nouns.","pattern":"**France**, **Tokyo**, **Mount Fuji**, **Lake Victoria**","commonMistakes":["The Hague is a city-name exception. Check unfamiliar names rather than guessing solely from the place category."],"examples":["Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of **—** France.” (— = no article)","Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of **—** Japan.” (— = no article)"],"skill":"form"},{"title":"Names that commonly take the","explanation":"River, sea, ocean and mountain-range names commonly take **the**. Some country names also do, especially plural names or names containing words such as Kingdom and Republic. Short and full official names can behave differently.","pattern":"**the Nile**, **the Alps**, **the United Kingdom**","commonMistakes":["Czechia normally has no article; the Czech Republic takes the. The chosen name matters."],"examples":["Complete ordinary naming inside an of-phrase: “The geography of **—** France was our subject.”","Complete ordinary naming inside an of-phrase: “The geography of **—** Japan was our subject.”"],"skill":"meaning"},{"title":"Institutional purpose and the building","explanation":"In British English, go to school, be in prison and be in hospital can refer to the institution’s usual role. The school or the hospital often identifies a particular building or site. American usage differs notably for in the hospital.","pattern":"The pupil is **at school**. / The builder is **at the school**.","commonMistakes":["Do not mark American in the hospital wrong without specifying the variety and intended meaning."],"examples":["Which category explains the ordinary article pattern for “France”? → **a country with an ordinary short name**","Which category explains the ordinary article pattern for “Japan”? → **a country with an ordinary short name**"],"skill":"contrast"},{"title":"Names inside larger noun phrases","explanation":"A geographical name can occur inside a larger noun phrase, where an article may belong to another noun. The history of France has the before history, not before France. A new context can also make a proper name descriptive: the Paris of my childhood.","pattern":"**The history of France** is the subject.","commonMistakes":["The exercises test ordinary geographical reference, not special descriptive or metaphorical uses of names."],"examples":["Choose the ordinary geographical name phrase to complete “Our lesson concerned **France**.” The place is france (a country with an ordinary short name).","Choose the ordinary geographical name phrase to complete “Our lesson concerned **Japan**.” The place is japan (a country with an ordinary short name)."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-zero-articles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"761255d5-4804-5a27-aef7-3e419b1ee6cb","topicSlug":"articles-place-names","level":"A2","prompt":"Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of ____ France.” (— = no article)","choices":[{"id":"A","text":"—"},{"id":"B","text":"a"},{"id":"C","text":"an"},{"id":"D","text":"the"}],"answerId":"A","hint":"Identify the name’s category: **a country with an ordinary short name**.","explanation":"In ordinary geographical reference, **France** uses no article because it is a country with an ordinary short name.","keywords":["geographic-article"],"skill":"geographic-article","contextKey":"articles-place-names-1","fingerprint":"1dcf052856c1fab4d6985c01b188d272c35f0bcae20a33aa81092dd105746a03","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-zero-articles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the name’s category: **a country with an ordinary short name**.","In ordinary geographical reference, **France** uses no article because it is a country with an ordinary short name.","Choose **—**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In ordinary geographical reference, **France** uses no article because it is a country with an ordinary short name.","B":"A would not give the ordinary identified geographical name in this context.","C":"An would not give the ordinary identified geographical name in this context.","D":"This ordinary use of the name takes **no article**: France."}}},{"id":"b6cde1a7-b963-56e7-a215-601bc0c724f5","topicSlug":"articles-place-names","level":"A2","prompt":"Complete ordinary naming inside an of-phrase: “The geography of ____ France was our subject.”","choices":[{"id":"A","text":"the"},{"id":"B","text":"—"},{"id":"C","text":"a"},{"id":"D","text":"an"}],"answerId":"B","hint":"The article before **geography** does not determine the article inside the following **of-phrase**.","explanation":"The first the belongs to geography. The place itself is still **France**.","keywords":["article-in-of-phrase"],"skill":"article-in-of-phrase","contextKey":"articles-place-names-1","fingerprint":"81d97530d1dba708982646a56d7f78bcb654c99fb0dd551622804d31c02bd5bd","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-zero-articles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The article before **geography** does not determine the article inside the following **of-phrase**.","The first the belongs to geography. The place itself is still **France**.","Choose **—**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The of-phrase does not change the ordinary naming pattern **France**.","B":"The first the belongs to geography. The place itself is still **France**.","C":"A does not give the ordinary geographical name here.","D":"An does not give the ordinary geographical name here."}}},{"id":"af7489aa-418a-54b1-a8ef-3e21d9f02009","topicSlug":"articles-place-names","level":"A2","prompt":"Which category explains the ordinary article pattern for “France”?","choices":[{"id":"A","text":"a verb describing movement"},{"id":"B","text":"a country with an ordinary short name"},{"id":"C","text":"a personal name"},{"id":"D","text":"an ordinary unnamed countable object"}],"answerId":"B","hint":"Identify the geographical category before applying its naming convention.","explanation":"The name **France** is a country with an ordinary short name; that category helps explain its conventional article use.","keywords":["name-category"],"skill":"name-category","contextKey":"articles-place-names-1","fingerprint":"be289a06b1deb26047170aed90a0d9c0c93c79bbde03d1d21a60a5edc6f2435c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-zero-articles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the geographical category before applying its naming convention.","The name **France** is a country with an ordinary short name; that category helps explain its conventional article use.","Choose **a country with an ordinary short name**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This does not describe the geographical name France; it is a country with an ordinary short name.","B":"The name **France** is a country with an ordinary short name; that category helps explain its conventional article use.","C":"This does not describe the geographical name France; it is a country with an ordinary short name.","D":"This does not describe the geographical name France; it is a country with an ordinary short name."}}},{"id":"d8c0fcaf-dc34-5368-a8fb-b575c9edf3eb","topicSlug":"articles-place-names","level":"A2","prompt":"Choose the ordinary geographical name phrase to complete “Our lesson concerned ____.” The place is france (a country with an ordinary short name).","choices":[{"id":"A","text":"an France"},{"id":"B","text":"the France"},{"id":"C","text":"France"},{"id":"D","text":"a France"}],"answerId":"C","hint":"Build the complete noun phrase from the place category and its established name.","explanation":"The complete ordinary name phrase is **France**. Keep the established article convention and the proper-name capitals.","keywords":["complete-name-phrase"],"skill":"complete-name-phrase","contextKey":"articles-place-names-1","fingerprint":"f8fb49134f51b7f3cf3a3cee8c90a0a803bdc1180ffd35b7a066194230a01f51","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-zero-articles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Build the complete noun phrase from the place category and its establish